import{_ as o,o as e,c as i,a8 as l}from"./chunks/framework.BppdKxCY.js";const m=JSON.parse('{"title":"EP.72 巨石应用的拆分术","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.72-micro-frontend.md","filePath":"comics/EP.72-micro-frontend.md","lastUpdated":1793706365000}'),r={name:"comics/EP.72-micro-frontend.md"};function t(n,a,s,d,c,u){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="ep-72-巨石应用的拆分术" tabindex="-1">EP.72 巨石应用的拆分术 <a class="header-anchor" href="#ep-72-巨石应用的拆分术" aria-label="Permalink to &quot;EP.72 巨石应用的拆分术&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../98-micro-frontend">98-micro-frontend.md</a>（98.1 生命周期 / 98.2 JS 沙箱 / 98.3 样式隔离 / 98.4 方案选型）· 示例：<code>examples/98-01-micro-frontend.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：子应用样式互相污染——.btn 全局生效。</li><li><strong>第 2 格</strong>：码叔揭秘 JS 沙箱（Proxy）+ 样式隔离（scoped/shadow DOM）。</li><li><strong>第 3 格</strong>：像素酱实证三种方案选型——qiankun/MF/wujie。</li><li><strong>第 4 格</strong>：码叔结案——生命周期与事件总线通信。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-样式污染" tabindex="-1">第 1 格 · 样式污染 <a class="header-anchor" href="#第-1-格-·-样式污染" aria-label="Permalink to &quot;第 1 格 · 样式污染&quot;">​</a></h3><ul><li>子应用 CSS 没有作用域，全局类名互相覆盖；</li><li>必须做样式隔离。</li></ul><h3 id="第-2-格-·-js-沙箱与样式隔离" tabindex="-1">第 2 格 · JS 沙箱与样式隔离 <a class="header-anchor" href="#第-2-格-·-js-沙箱与样式隔离" aria-label="Permalink to &quot;第 2 格 · JS 沙箱与样式隔离&quot;">​</a></h3><ul><li>JS 沙箱：Proxy 代理 window，写入进私有副本不污染主应用；</li><li>样式隔离：scoped（前缀）、shadow DOM、CSS Modules。</li></ul><h3 id="第-3-格-·-方案选型" tabindex="-1">第 3 格 · 方案选型 <a class="header-anchor" href="#第-3-格-·-方案选型" aria-label="Permalink to &quot;第 3 格 · 方案选型&quot;">​</a></h3><ul><li>qiankun：多技术栈、存量应用多；</li><li>Module Federation：同技术栈、新应用；</li><li>wujie：老旧应用、需强隔离。</li></ul><h3 id="第-4-格-·-生命周期与通信" tabindex="-1">第 4 格 · 生命周期与通信 <a class="header-anchor" href="#第-4-格-·-生命周期与通信" aria-label="Permalink to &quot;第 4 格 · 生命周期与通信&quot;">​</a></h3><ul><li>生命周期：bootstrap→mount→unmount；</li><li>通信：全局事件总线，事件名加应用前缀。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../98-micro-frontend#_98-7-本章避坑清单">《98.7 本章避坑清单》</a></p></blockquote><ol><li>子应用挂 window 变量 → 用沙箱私有域；</li><li>样式冲突 → CSS Modules 或 strictStyleIsolation；</li><li>定时器没清 → unmount 里清所有监听。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>JS 沙箱 Proxy 方案怎么隔离全局变量？——<strong>写入进私有 fakeWindow，读取先查私有再回退真实 window</strong>。</li><li>qiankun 和 wujie 的核心区别？——<strong>qiankun 用 Proxy 沙箱+HTML Entry，wujie 用 iframe 实现强隔离</strong>。</li><li>子应用之间怎么通信？——<strong>全局事件总线发布订阅，事件名加应用前缀</strong>。</li></ol>',18)])])}const f=o(r,[["render",t]]);export{m as __pageData,f as default};
